import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ code for custom elementwise add, ReLU, and ReLU6
source_code = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Elementwise Add
__global__ void add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}

// Standard ReLU
__global__ void relu_kernel(const float* in, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        out[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor relu_cuda(torch::Tensor in) {
    auto out = torch::zeros_like(in);
    auto size = in.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(in.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}

// ReLU6
__global__ void relu6_kernel(const float* in, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        val = val > 0.0f ? val : 0.0f;
        val = val < 6.0f ? val : 6.0f;
        out[idx] = val;
    }
}

torch::Tensor relu6_cuda(torch::Tensor in) {
    auto out = torch::zeros_like(in);
    auto size = in.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu6_kernel<<<num_blocks, block_size>>>(in.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
"""

cpp_declarations = r"""
torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);
torch::Tensor relu_cuda(torch::Tensor in);
torch::Tensor relu6_cuda(torch::Tensor in);
"""

custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=cpp_declarations,
    cuda_sources=source_code,
    functions=["elementwise_add_cuda", "relu_cuda", "relu6_cuda"],
    verbose=False
)

# Simple nn.Module wrappers for the custom CUDA ops
class CustomAdd(nn.Module):
    def __init__(self):
        super(CustomAdd, self).__init__()

    def forward(self, x, y):
        return custom_ops.elementwise_add_cuda(x, y)

class CustomReLU(nn.Module):
    def __init__(self):
        super(CustomReLU, self).__init__()

    def forward(self, x):
        return custom_ops.relu_cuda(x)

class CustomReLU6(nn.Module):
    def __init__(self):
        super(CustomReLU6, self).__init__()

    def forward(self, x):
        return custom_ops.relu6_cuda(x)


class MBConvNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, expand_ratio):
        """
        MBConv block implementation with custom CUDA ops for skip-connection and ReLU6.
        """
        super(MBConvNew, self).__init__()

        self.use_residual = (stride == 1 and in_channels == out_channels)
        self.add_op = CustomAdd()
        self.relu6 = CustomReLU6()
        hidden_dim = in_channels * expand_ratio

        if expand_ratio != 1:
            self.expand_conv = nn.Sequential(
                nn.Conv2d(in_channels, hidden_dim, kernel_size=1, stride=1, padding=0, bias=False),
                nn.BatchNorm2d(hidden_dim),
            )
        else:
            self.expand_conv = None

        self.depthwise_conv = nn.Sequential(
            nn.Conv2d(hidden_dim, hidden_dim, kernel_size=kernel_size, stride=stride, 
                      padding=(kernel_size-1)//2, groups=hidden_dim, bias=False),
            nn.BatchNorm2d(hidden_dim),
        )

        self.project_conv = nn.Sequential(
            nn.Conv2d(hidden_dim, out_channels, kernel_size=1, stride=1, padding=0, bias=False),
            nn.BatchNorm2d(out_channels)
        )

    def forward(self, x):
        identity = x

        if self.expand_conv is not None:
            x = self.expand_conv(x)
            x = self.relu6(x)  # custom ReLU6 after expansion

        x = self.depthwise_conv(x)
        x = self.relu6(x)      # custom ReLU6 after depthwise
        x = self.project_conv(x)

        if self.use_residual:
            x = self.add_op(x, identity)  # custom elementwise add for skip

        return x


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        """
        Optimized EfficientNetB0 with custom CUDA operators.
        """
        super(ModelNew, self).__init__()

        self.relu = CustomReLU()
        self.conv1 = nn.Conv2d(3, 32, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(32)

        self.blocks = nn.Sequential(
            MBConvNew(32, 16, kernel_size=3, stride=1, expand_ratio=1),
            MBConvNew(16, 24, kernel_size=3, stride=2, expand_ratio=6),
            MBConvNew(24, 24, kernel_size=3, stride=1, expand_ratio=6),
            MBConvNew(24, 40, kernel_size=5, stride=2, expand_ratio=6),
            MBConvNew(40, 40, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(40, 80, kernel_size=3, stride=2, expand_ratio=6),
            MBConvNew(80, 80, kernel_size=3, stride=1, expand_ratio=6),
            MBConvNew(80, 112, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(112, 112, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(112, 192, kernel_size=5, stride=2, expand_ratio=6),
            MBConvNew(192, 192, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(192, 192, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(192, 320, kernel_size=3, stride=1, expand_ratio=6)
        )

        self.conv2 = nn.Conv2d(320, 1280, kernel_size=1, stride=1, padding=0, bias=False)
        self.bn2 = nn.BatchNorm2d(1280)
        self.fc = nn.Linear(1280, num_classes)

    def forward(self, x):
        x = self.bn1(self.conv1(x))
        x = self.relu(x)  # custom ReLU for first conv
        x = self.blocks(x)
        x = self.bn2(self.conv2(x))
        x = self.relu(x)  # custom ReLU for final conv
        x = F.adaptive_avg_pool2d(x, (1, 1))
        x = x.view(x.size(0), -1)
        x = self.fc(x)
        return x


